import glob
import re
import ast

def get_scope(file_path, func_name, args, return_keys):
    if 'payload' in args:
        return 'write'
    if 'created' in return_keys or 'updated' in return_keys:
        return 'write'
    for kw in ['create', 'update', 'delete', 'save', 'write']:
        if kw in func_name.lower():
            return 'write'
    return 'read'

files_migrated = 0

for f in sorted(glob.glob('app/**/*.py', recursive=True)):
    if f == 'app/auth.py':
        continue
    with open(f, 'r', encoding='utf-8') as file:
        content = file.read()

    if 'legacy_auth' not in content:
        continue

    tree = ast.parse(content)

    lines = content.splitlines(keepends=True)

    func_scopes = []
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            has_legacy_auth = False
            for sub in ast.walk(node):
                if isinstance(sub, ast.Call) and isinstance(sub.func, ast.Name) and sub.func.id == 'legacy_auth':
                    has_legacy_auth = True
                    break
            if has_legacy_auth:
                args = [a.arg for a in node.args.args]
                ret_keys = []
                for sub in ast.walk(node):
                    if isinstance(sub, ast.Return) and isinstance(sub.value, ast.Dict):
                        ret_keys = [ast.literal_eval(k) for k in sub.value.keys if isinstance(k, ast.Constant)]
                scope = get_scope(f, node.name, args, ret_keys)
                func_scopes.append({
                    'start_line': node.lineno,
                    'end_line': node.end_lineno,
                    'scope': scope
                })

    func_scopes.sort(key=lambda x: x['start_line'], reverse=True)

    for f_scope in func_scopes:
        start_idx = f_scope['start_line'] - 1
        end_idx = f_scope['end_line']
        scope_str = f_scope['scope']

        func_lines = lines[start_idx:end_idx]
        new_func_lines = []
        for line in func_lines:
            new_line = re.sub(
                r'legacy_auth\(([^)]+)\)',
                rf'new_auth(\1, scope="{scope_str}")',
                line
            )
            new_func_lines.append(new_line)
        lines[start_idx:end_idx] = new_func_lines

    new_content = "".join(lines)

    new_content = new_content.replace(
        'from app.auth import legacy_auth',
        'from app.auth import new_auth'
    )

    with open(f, 'w', encoding='utf-8') as file:
        file.write(new_content)
    files_migrated += 1

print(f"Migration completed! Migrated {files_migrated} files.")
